{
  "$schema": "https://anthropic.com/claude-code/marketplace.schema.json",
  "name": "wisp-plugins",
  "description": "Wisp Plugins: ten cooperating plugins covering the full development lifecycle \u2014 from requirement capture through spec, plan, implementation, verification, and shipping.",
  "owner": {
    "name": "Gabriel Castro",
    "email": "gabe@techworx.dev"
  },
  "plugins": [
    {
      "name": "mason",
      "description": "Meta-plugin for scaffolding and auditing plugins, skills, and subagents. Generates plugin directory structure, validates conformance to ecosystem schemas, and designs shared schema contracts. Skills: scaffold-plugin, audit-plugin, design-schema, scaffold-subagent.",
      "source": "./plugins/mason"
    },
    {
      "name": "ranger",
      "description": "Cross-language bug hunting. Finds real bugs in live code through recon, hazard scanning, adversarial verification, and exit-gate verdict. Supersedes bug-hunter-rust and bug-hunter-ts.",
      "source": "./plugins/ranger"
    },
    {
      "name": "sentinel",
      "description": "Cross-cutting verification gate. Confirms that any stage artifact meets its criteria before the next stage begins. One skill, one recon-verify-judge pipeline, reused unchanged against any artifact type.",
      "source": "./plugins/sentinel"
    },
    {
      "name": "weaver",
      "description": "Need definition plugin. Captures and structures requirements before implementation begins. Integrates with GitHub Issues by default; extensible to Linear, Jira, or any issue tracker that produces the requirement@1 schema. Skills: capture-need, clarify-requirement, prioritize-backlog, connect-requirement, audit-backlog.",
      "source": "./plugins/weaver"
    },
    {
      "name": "vanguard",
      "description": "Research plugin. Investigates questions and requirements to build a documented evidence base before committing to a solution direction. Produces research-report@1.",
      "source": "./plugins/vanguard"
    },
    {
      "name": "scribe",
      "description": "Specification plugin. Turns requirements and research reports into unambiguous, testable specs. Detects spec drift against actual code. Skills: draft-spec, verify-spec, spec-drift, audit-spec, gate-spec, correct-spec, architect.",
      "source": "./plugins/scribe"
    },
    {
      "name": "muse",
      "description": "Component specification plugin. Turns UI/design intent into unambiguous, testable component specs \u2014 props, variants, per-state behavior, and accessibility criteria as testable propositions, gated before planning. Also sketches options before anything is specified (sketch) and carries a chosen option into a requirement (promote).",
      "source": "./plugins/muse"
    },
    {
      "name": "navigator",
      "description": "Planning plugin. Decomposes specs into sequenced, bite-sized implementation plans with an implementation approach, exact code as a baseline, and the tests proving each criterion \u2014 no write-test-first mandate. Tasks are sized to compilation boundaries, not a clock-time estimate. No TBDs. A developer with zero domain context can execute the plan mechanically.",
      "source": "./plugins/navigator"
    },
    {
      "name": "smith",
      "description": "Implementation plugin. Executes plans by designing the approach, implementing, and writing comprehensive tests proving each acceptance criterion \u2014 verified by mutation testing, not a write-test-first mandate. The plan's code is a baseline implementer may improve on in shape, not scope. Produces committed, tested code verified by the sentinel exit gate. Also spikes: a throwaway experiment that checks whether a tool or approach works (spike).",
      "source": "./plugins/smith"
    },
    {
      "name": "courier",
      "description": "Shipping plugin. Shepherds completed code through commit, PR creation, review response, and changeset documentation. Skills: commit, pr, changeset, receive-feedback, post-review, release.",
      "source": "./plugins/courier"
    }
  ]
