1	//! Version-pinned schema contracts for Wisp artifacts.
2	
3	use miette::{Diagnostic, NamedSource, SourceSpan};
4	use serde_json::Value;
5	use thiserror::Error;
6	use wisp_model::{ArtifactId, ArtifactIdError};
7	
8	/// The JSON Schema identifier for the spec contract.
9	pub const SPEC_V1_SCHEMA_ID: &str = "spec@1";
10	
11	/// Portable canonical contracts supported by Wisp's initial registry.
12	#[derive(Clone, Copy, Debug, Eq, PartialEq)]
13	pub enum Contract {
14	    /// A captured need.
15	    RequirementV1,
16	    /// Evidence informing a requirement.
17	    ResearchReportV1,
18	    /// A testable specification.
19	    SpecV1,
20	    /// An implementation plan.
21	    PlanV1,
22	    /// A workspace architecture map.
23	    ArchModelV1,
24	    /// A workspace architecture map with optional decision references.
25	    ArchModelV2,
26	}
27	
28	impl Contract {
29	    /// Stable schema identifier.
30	    #[must_use]
31	    pub const fn id(self) -> &'static str {
32	        match self {
33	            Self::RequirementV1 => "requirement@1",
34	            Self::ResearchReportV1 => "research-report@1",
35	            Self::SpecV1 => "spec@1",
36	            Self::PlanV1 => "plan@1",
37	            Self::ArchModelV1 => "arch-model@1",
38	            Self::ArchModelV2 => "arch-model@2",
39	        }
40	    }
41	
42	    /// Canonical workspace-relative path pattern.
43	    #[must_use]
44	    pub const fn canonical_directory(self) -> &'static str {
45	        match self {
46	            Self::RequirementV1 => "docs/requirements",
47	            Self::ResearchReportV1 => "docs/research",
48	            Self::SpecV1 => "docs/specs",
49	            Self::PlanV1 => "docs/projects",
50	            Self::ArchModelV1 | Self::ArchModelV2 => "docs/architecture",
51	        }
52	    }
53	
54	    /// Resolve an exact registered schema identifier.
55	    ///
56	    /// # Errors
57	    ///
58	    /// Returns [`ContractLookupError::UnknownContract`] when `id` is not
59	    /// registered.
60	    pub fn from_id(id: &str) -> Result<Self, ContractLookupError> {
61	        match id {
62	            "requirement@1" => Ok(Self::RequirementV1),
63	            "research-report@1" => Ok(Self::ResearchReportV1),
64	            "spec@1" => Ok(Self::SpecV1),
65	            "plan@1" => Ok(Self::PlanV1),
66	            "arch-model@1" => Ok(Self::ArchModelV1),
67	            "arch-model@2" => Ok(Self::ArchModelV2),
68	            _ => Err(ContractLookupError::UnknownContract { id: id.to_owned() }),
69	        }
70	    }
71	}
72	
73	/// Failure returned when an exact schema identifier is not registered.
74	#[derive(Debug, Diagnostic, Error, Eq, PartialEq)]
75	pub enum ContractLookupError {
76	    /// The requested contract identifier is unknown to this registry.
77	    #[diagnostic(code(wisp::schema::unknown_contract))]
78	    #[error("unknown artifact contract ID: {id}")]
79	    UnknownContract {
80	        /// The exact identifier supplied by the caller.
81	        id: String,
82	    },
83	}
84	
85	const EMBEDDED_SPEC_V1_SCHEMA: &str = include_str!("../../../schemas/spec@1.json");
86	const EMBEDDED_REQUIREMENT_V1_SCHEMA: &str = include_str!("../../../schemas/requirement@1.json");
87	const EMBEDDED_RESEARCH_REPORT_V1_SCHEMA: &str = include_str!("../../../schemas/research-report@1.json");
88	const EMBEDDED_PLAN_V1_SCHEMA: &str = include_str!("../../../schemas/plan@1.json");
89	const EMBEDDED_ARCH_MODEL_V1_SCHEMA: &str = include_str!("../../../schemas/arch-model@1.json");
90	const EMBEDDED_ARCH_MODEL_V2_SCHEMA: &str = include_str!("../../../schemas/arch-model@2.json");
91	const EMBEDDED_IMPLEMENTATION_CONTEXT_V1_SCHEMA: &str = include_str!("../../../schemas/implementation-context@1.json");
92	
93	/// Validate a parsed document against a selected pinned contract.
94	///
95	/// # Errors
96	///
97	/// Returns a typed error when the embedded schema is invalid or the document
98	/// does not conform to it.
99	pub fn validate_contract(contract: Contract, value: &Value) -> Result<(), SpecValidationError> {
100	    let source = match contract {
101	        Contract::RequirementV1 => EMBEDDED_REQUIREMENT_V1_SCHEMA,
102	        Contract::ResearchReportV1 => EMBEDDED_RESEARCH_REPORT_V1_SCHEMA,
103	        Contract::SpecV1 => EMBEDDED_SPEC_V1_SCHEMA,
104	        Contract::PlanV1 => EMBEDDED_PLAN_V1_SCHEMA,
105	        Contract::ArchModelV1 => EMBEDDED_ARCH_MODEL_V1_SCHEMA,
106	        Contract::ArchModelV2 => EMBEDDED_ARCH_MODEL_V2_SCHEMA,
107	    };
108	    validate_embedded_schema(contract.id(), source, value)
109	}
110	
111	/// Validate a transient implementation-context result against its pinned wire contract.
112	///
113	/// This output schema has no canonical workspace directory and is not an
114	/// artifact variant in [`Contract`].
115	///
116	/// # Errors
117	///
118	/// Returns a typed error when the embedded schema is invalid or the result
119	/// violates implementation-context@1.
120	pub fn validate_implementation_context(value: &Value) -> Result<(), SpecValidationError> {
121	    validate_embedded_schema("implementation-context@1", EMBEDDED_IMPLEMENTATION_CONTEXT_V1_SCHEMA, value)
122	}
123	
124	fn validate_embedded_schema(contract_id: &'static str, source: &str, value: &Value) -> Result<(), SpecValidationError> {
125	    let schema: Value = serde_json::from_str(source)
126	        .map_err(|error| SpecValidationError::SchemaDefinition { contract_id, message: error.to_string() })?;
127	    let validator = jsonschema::validator_for(&schema)
128	        .map_err(|error| SpecValidationError::SchemaDefinition { contract_id, message: error.to_string() })?;
129	    validator
130	        .validate(value)
131	        .map_err(|error| SpecValidationError::SchemaViolation { contract_id, message: error.to_string() })
132	}
133	
134	/// A `spec@1` document that has passed both its JSON Schema and Wisp ID checks.
135	#[derive(Debug, Clone, PartialEq)]
136	pub struct ValidatedSpec {
137	    /// The validated artifact identifier.
138	    pub id: ArtifactId,
139	    /// The original parsed JSON document.
140	    pub value: Value,
141	}
142	
143	/// An error encountered while parsing or validating a `spec@1` document.
144	#[derive(Debug, Diagnostic, Error)]
145	pub enum SpecValidationError {
146	    /// The candidate bytes are not valid JSON.
147	    #[diagnostic(code(wisp::schema::invalid_json))]
148	    #[error("the spec document is not valid JSON: {source}")]
149	    InvalidJson {
150	        /// Candidate source used by human diagnostics.
151	        #[source_code]
152	        source_code: NamedSource<String>,
153	        /// The parser location in the candidate source.
154	        #[label("invalid JSON here")]
155	        span: SourceSpan,
156	        /// The underlying JSON parser error.
157	        #[source]
158	        source: serde_json::Error,
159	    },
160	    /// The embedded schema could not be compiled.
161	    #[diagnostic(code(wisp::schema::definition))]
162	    #[error("the embedded {contract_id} schema is invalid: {message}")]
163	    SchemaDefinition {
164	        /// The registered contract whose schema could not be compiled.
165	        contract_id: &'static str,
166	        /// A stable diagnostic suitable for logs, not terminal presentation.
167	        message: String,
168	    },
169	    /// The candidate does not satisfy the `spec@1` JSON Schema.
170	    #[diagnostic(code(wisp::schema::violation))]
171	    #[error("the document violates {contract_id}: {message}")]
172	    SchemaViolation {
173	        /// The registered contract selected for validation.
174	        contract_id: &'static str,
175	        /// The first validator diagnostic.
176	        message: String,
177	    },
178	    /// The schema-valid `id` is not safe for a Wisp artifact path.
179	    #[diagnostic(code(wisp::schema::unsafe_id))]
180	    #[error("the spec document has an unsafe ID: {source}")]
181	    UnsafeId {
182	        /// The artifact ID validation error.
183	        #[source]
184	        source: ArtifactIdError,
185	    },
186	}
187	
188	/// Parse and validate candidate JSON bytes as a `spec@1` document.
189	///
190	/// # Errors
191	///
192	/// Returns an error when the bytes are malformed, the document violates the
193	/// pinned schema, or its otherwise schema-valid ID is unsafe for Wisp paths.
194	pub fn validate_spec_json(input: &[u8]) -> Result<ValidatedSpec, SpecValidationError> {
195	    let value = serde_json::from_slice(input).map_err(|source| invalid_json(input, source))?;
196	    validate_spec_value(value)
197	}
198	
199	/// Validate an already parsed JSON value as a `spec@1` document.
200	///
201	/// # Errors
202	///
203	/// Returns an error when the document violates the pinned schema or its ID is
204	/// unsafe for Wisp artifact paths.
205	pub fn validate_spec_value(value: Value) -> Result<ValidatedSpec, SpecValidationError> {
206	    let schema: Value = serde_json::from_str(EMBEDDED_SPEC_V1_SCHEMA).map_err(|source| {
207	        SpecValidationError::SchemaDefinition { contract_id: SPEC_V1_SCHEMA_ID, message: source.to_string() }
208	    })?;
209	    let validator = jsonschema::validator_for(&schema).map_err(|error| SpecValidationError::SchemaDefinition {
210	        contract_id: SPEC_V1_SCHEMA_ID,
211	        message: error.to_string(),
212	    })?;
213	    if let Err(error) = validator.validate(&value) {
214	        return Err(SpecValidationError::SchemaViolation {
215	            contract_id: SPEC_V1_SCHEMA_ID,
216	            message: error.to_string(),
217	        });
218	    }
219	
220	    let id = value.get("id").and_then(Value::as_str).ok_or_else(|| SpecValidationError::SchemaViolation {
221	        contract_id: SPEC_V1_SCHEMA_ID,
222	        message: "spec@1 accepted a document without a string id".to_owned(),
223	    })?;
224	    let id = ArtifactId::new(id).map_err(|source| SpecValidationError::UnsafeId { source })?;
225	
226	    Ok(ValidatedSpec { id, value })
227	}
228	
229	fn invalid_json(input: &[u8], source: serde_json::Error) -> SpecValidationError {
230	    let source_text = String::from_utf8_lossy(input).into_owned();
231	    let line = source.line().saturating_sub(1);
232	    let column = source.column().saturating_sub(1);
233	    let line_offset = source_text.lines().take(line).map(|line| line.len() + 1).sum::<usize>();
234	    let offset = line_offset.saturating_add(column).min(source_text.len());
235	    SpecValidationError::InvalidJson {
236	        source_code: NamedSource::new("spec candidate", source_text),
237	        span: SourceSpan::from((offset, 1)),
238	        source,
239	    }
240	}
